<?php
/**
 * Plugin Name: DK Content Override (yeni içerik)
 * Description: dk-content.php'nin handle_virtual_pages ve inject_homepage_content işlerini yeni HTML'lerle override eder. Sayfa metinleri akademik dile uyarlandı, Numap kapsamı 48-119 ay olarak güncellendi, isim atıfları kaldırıldı.
 * Version: 1.0
 * Author: Diskalkuli Akademi
 */
if (!defined('ABSPATH')) exit;

class DK_Override {
  // gzip + base64 encoded HTMLs (tek seferde decode edilir)
  private static $PAGES = [
    'anasayfa' => '',
    'diskalkuli-nedir' => '',
    'ebeveynler' => '',
    'ogretmenler' => '',
    'araclar' => '',
    'hakkimizda' => '',
    'yilmaz-mutlu' => '',
  ];

  public function __construct() {
    // priority 1 — dk-content.php'nin priority 10'undan ÖNCE çalışsın
    add_action('template_redirect', [$this, 'handle_virtual'], 1);
    add_filter('the_content', [$this, 'override_homepage_content'], 99);
  }

  private static function get_page_html($slug) {
    if (!isset(self::$PAGES[$slug])) return null;
    $bin = base64_decode(self::$PAGES[$slug]);
    if ($bin === false) return null;
    $html = gzdecode($bin);
    return $html ?: null;
  }

  /**
   * URL'ye göre virtual page render et + exit.
   * dk-content.php'nin aynı işi priority 10'da yapar — biz priority 1 ile önce yakalarız.
   */
  public function handle_virtual() {
    $uri = parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH);
    $uri = '/' . trim($uri, '/') . '/';
    $map = [
      '/diskalkuli-nedir/' => 'diskalkuli-nedir',
      '/ebeveynler/' => 'ebeveynler',
      '/ogretmenler/' => 'ogretmenler',
      '/araclar/' => 'araclar',
      '/yilmaz-mutlu/' => 'yilmaz-mutlu',
    ];
    if (!isset($map[$uri])) return;
    $slug = $map[$uri];
    $html = self::get_page_html($slug);
    if (!$html) return;

    // Tema header/footer'ı kullan ki menü ve footer korunsun
    // Custom title set
    add_filter('pre_get_document_title', function() use ($slug) {
      $titles = [
        'diskalkuli-nedir' => 'Diskalkuli Nedir? — Akademik Rehber | Diskalkuli Akademi',
        'ebeveynler' => 'Ebeveynler için Diskalkuli Rehberi | Diskalkuli Akademi',
        'ogretmenler' => 'Öğretmenler için Diskalkuli Rehberi | Diskalkuli Akademi',
        'araclar' => 'DokunSay Araçları — 7 İnteraktif Matematik Öğretim Aracı | Diskalkuli Akademi',
        'yilmaz-mutlu' => 'Prof. Dr. Yılmaz Mutlu — Akademik Profil | Diskalkuli Akademi',
      ];
      return $titles[$slug] ?? '';
    }, 100);

    status_header(200);
    nocache_headers();
    get_header();
    echo '<main id="main-content" class="dk-main-content site-main" style="display:block;width:100%;min-height:60vh;">';
    echo $html;
    echo '</main>';
    get_footer();
    exit;
  }

  /**
   * Anasayfa içeriği — page-id-6294 için the_content filter'ı ile inject.
   */
  public function override_homepage_content($content) {
    if (!is_front_page() && !is_home()) return $content;
    $html = self::get_page_html('anasayfa');
    if ($html) return $html;
    return $content;
  }
}

new DK_Override();
